python3 - <<'EOF'
import re
lines=open('docs/dev/package-sync-scenario-coverage.md').read().split('\n')
marks={}
for l in lines:
    if not l.startswith('| '): continue
    c=[x.strip() for x in l.strip().strip('|').split('|')]
    if len(c)<3: continue
    if re.fullmatch(r'[A-KN]\d+', c[0]): marks[c[0]]=c[-2]
start=lines.index('## Gaps — what to test next')
end=lines.index('### What has no VM coverage at all')
# entries can wrap lines; join continuation lines
entries=[]
cur=None
for l in lines[start:end]:
    m=re.match(r'- \*\*([A-KN]\d+)\*\*(.*)', l)
    if m:
        if cur: entries.append(cur)
        cur=[m.group(1), m.group(2)]
    elif cur is not None and l.strip():
        cur[1]+=' '+l.strip()
if cur: entries.append(cur)
print("entries:", len(entries))
from collections import Counter
print(Counter(marks.get(e[0],'MISSING') for e in entries))
# do U-headed entries reference an open row in their body?
open_marks={'—','‼','P'}
u_entries=[e for e in entries if marks.get(e[0])=='U']
withopen=[]
for rid,body in u_entries:
    others={i for i in re.findall(r'\b([A-KN]\d{1,3})\b', body) if i in marks and i!=rid}
    op={i for i in others if marks[i] in open_marks}
    if op: withopen.append((rid, sorted(op)))
print("U-headed entries whose body names an open row:", len(withopen))
for x in withopen: print("  ", x)
EOF
